<script setup lang="ts">
import { computed, inject, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ArrowRight, Braces, Check, ChevronDown, Code2, Database, FileText, GitCommitHorizontal, LoaderCircle, Play, RefreshCw, Search, ShieldCheck, Sparkles, Table2, X } from 'lucide-vue-next';
import type { BranchItem, FilePreview, FileTreeNode, QueryResult, TableColumn } from '@oxen/shared';
import { post, queryString, request } from '../api';
import { useAppStore } from '../stores/app';
import FileTree from './FileTree.vue';
const props=defineProps<{base:string;branch:string}>(),app=useAppStore(),route=useRoute(),router=useRouter();
const initialPath=typeof route.query.path==='string'?route.query.path:'';
const path=ref(initialPath),draftPath=ref(initialPath),prompt=ref(typeof route.query.prompt==='string'?route.query.prompt:''),engine=ref<'model'|'rules'>(route.query.engine==='rules'?'rules':'model'),allowExternalSchema=ref(false);
const result=ref<QueryResult>(),loading=ref(false),error=ref(''),sourceLoading=ref(false),sourceError=ref(''),sourceCommit=ref(''),sourceRows=ref<number>(),columns=ref<TableColumn[]>([]),showPicker=ref(!initialPath),showFields=ref(false),resultView=ref<'rows'|'plan'>('rows');
const context=ref<{ref:string;path:string;prompt:string}>();
const openIdentity=inject<()=>void>('openIdentityDialog',()=>{});
const supported=computed(()=>app.status?.capabilities.naturalLanguageQuery===true||app.status?.mode==='demo');
const authenticated=computed(()=>app.status?.authenticated===true);
const ready=computed(()=>supported.value&&authenticated.value&&!!sourceCommit.value&&!sourceLoading.value);
const canRun=computed(()=>ready.value&&!loading.value&&!!prompt.value.trim()&&(engine.value==='rules'||allowExternalSchema.value));
const fileName=computed(()=>path.value.split('/').pop()||'选择数据文件');
const suggestions=computed(()=>{
  const numeric=columns.value.find(column=>/number|int|float|decimal|[if]\d+/i.test(column.dtype));
  if(engine.value==='rules')return ['前 10 行','统计总数',...(numeric?[`按 ${numeric.name} 降序 前 20 行`]:[])];
  return ['显示前 20 条记录','统计记录总数',...(numeric?[`按 ${numeric.name} 从大到小排序，显示前 10 条`]:[])];
});
const returnedRange=computed(()=>{const value=result.value;if(!value)return {offset:0,start:0,end:0,limit:undefined as number|undefined,partial:false};const plan=value.plan&&typeof value.plan==='object'&&!Array.isArray(value.plan)?value.plan as Record<string,unknown>:undefined;const offset=typeof plan?.offset==='number'&&Number.isFinite(plan.offset)?Math.max(0,Math.trunc(plan.offset)):0;const limit=typeof plan?.limit==='number'&&Number.isFinite(plan.limit)?Math.max(1,Math.trunc(plan.limit)):undefined;const count=value.rows.length;return {offset,start:count?offset+1:0,end:count?offset+count:0,limit,partial:count<value.totalRows||offset>0&&value.totalRows>0};});
let generation=0,sourceGeneration=0;
function reset(){++generation;result.value=undefined;context.value=undefined;error.value='';loading.value=false;resultView.value='rows';}
async function loadSource(){
  const current=++sourceGeneration;sourceLoading.value=true;sourceError.value='';sourceCommit.value='';columns.value=[];sourceRows.value=undefined;reset();
  if(!path.value.trim()){sourceLoading.value=false;showPicker.value=true;return;}
  const base=props.base,branch=props.branch,filename=path.value.trim();
  try{const branches=await request<BranchItem[]>(base+'/branches');if(current!==sourceGeneration)return;const reference=branches.find(item=>item.name===branch)?.commitId??branch;const value=await request<FilePreview>(base+'/file'+queryString({ref:reference,path:filename,page:1,pageSize:1}));if(current!==sourceGeneration)return;if(value.kind!=='table')throw new Error('请选择 JSONL、CSV、TSV、Parquet 或 Arrow 表格文件。');columns.value=value.columns??[];sourceRows.value=value.totalRows;sourceCommit.value=reference;showPicker.value=false;}
  catch(cause){if(current===sourceGeneration)sourceError.value=(cause as Error).message;}
  finally{if(current===sourceGeneration)sourceLoading.value=false;}
}
async function selectPath(){const filename=draftPath.value.trim();if(!filename)return;if(filename===path.value){await loadSource();return;}allowExternalSchema.value=false;await router.replace({query:{branch:props.branch,path:filename,engine:engine.value}});}
async function selectFile(node:FileTreeNode){if(node.kind==='directory')return;if(!/\.(jsonl|ndjson|csv|tsv|parquet|arrow)$/i.test(node.path)){sourceError.value='这个文件不是支持查询的表格格式。请选择数据文件。';return;}draftPath.value=node.path;await selectPath();}
async function run(){
  if(!canRun.value)return;reset();const current=generation;
  const input={ref:sourceCommit.value,path:path.value.trim(),prompt:prompt.value.trim(),engine:engine.value,allowExternalSchema:allowExternalSchema.value};loading.value=true;
  try{const value=await post<QueryResult>(props.base+'/query',input);if(current===generation){result.value=value;context.value=input;}}
  catch(cause){if(current===generation)error.value=(cause as Error).message;}
  finally{if(current===generation)loading.value=false;}
}
function insertField(name:string){prompt.value=prompt.value.trim()?prompt.value.trim()+' '+name:name;}
function cell(value:unknown){return typeof value==='object'&&value!==null?JSON.stringify(value):value===null?'null':String(value??'');}
function example(value:string){prompt.value=value;}
watch(()=>[props.base,props.branch,route.query.path],()=>{path.value=typeof route.query.path==='string'?route.query.path:'';draftPath.value=path.value;allowExternalSchema.value=false;void loadSource();},{immediate:true});
watch(engine,()=>{reset();allowExternalSchema.value=false;});
onBeforeUnmount(()=>{++generation;++sourceGeneration;});
</script>

<template>
  <section class="query-workbench" aria-label="数据查询工作台">
    <header class="query-resource-bar"><div class="query-resource"><Database :size="18"/><strong>{{fileName}}</strong><span v-if="sourceRows!==undefined" class="badge">{{sourceRows.toLocaleString()}} 行</span><code v-if="sourceCommit" :title="sourceCommit">{{sourceCommit.slice(0,10)}}</code></div><div><button class="btn btn-ghost" :aria-expanded="showPicker" @click="showPicker=!showPicker"><FileText :size="14"/>{{path?'更换数据文件':'选择数据文件'}}<ChevronDown :size="13"/></button><button v-if="path" class="icon-button" aria-label="刷新数据版本" :disabled="sourceLoading||loading" @click="loadSource"><RefreshCw :size="15" :class="{spin:sourceLoading}"/></button></div></header>
    <section v-if="showPicker" class="query-source-picker panel"><header><div><h3>选择数据文件</h3><p>选择仓库中的表格，或输入文件路径。</p></div><button v-if="sourceCommit" class="icon-button" aria-label="关闭数据文件选择器" @click="showPicker=false"><X :size="17"/></button></header><form @submit.prevent="selectPath"><label class="field">数据文件路径<input v-model="draftPath" placeholder="例如：data/samples.jsonl" required/></label><button class="btn" :disabled="sourceLoading"><LoaderCircle v-if="sourceLoading" class="spin" :size="15"/><ArrowRight v-else :size="15"/>加载数据</button></form><div class="source-file-tree"><FileTree :key="base+branch" :base="base" :branch="branch" :tabular-only="true" @select="selectFile"/></div></section>
    <div v-if="sourceError" class="error-state" role="alert"><span>{{sourceError}}</span><button class="btn" @click="showPicker=true">选择其他文件</button></div>
    <div class="query-layout">
      <div class="query-main">
        <section class="query-composer panel">
          <div class="query-mode-bar"><div class="query-modes" role="group" aria-label="查询方式"><button :disabled="sourceLoading" :class="{active:engine==='model'}" :aria-pressed="engine==='model'" @click="engine='model'"><Sparkles :size="15"/>自然语言</button><button :disabled="sourceLoading" :class="{active:engine==='rules'}" :aria-pressed="engine==='rules'" @click="engine='rules'"><Code2 :size="15"/>规则查询</button></div><span class="readonly-indicator"><ShieldCheck :size="13"/>只读查询</span></div>
          <form @submit.prevent="run"><div class="query-editor"><span class="query-prompt-icon"><Sparkles v-if="engine==='model'" :size="19"/><Search v-else :size="19"/></span><label class="sr-only" :for="engine==='model'?'natural-query-input':'rule-query-input'">{{engine==='model'?'自然语言问题':'规则表达式'}}</label><textarea :id="engine==='model'?'natural-query-input':'rule-query-input'" v-model="prompt" rows="4" maxlength="4000" required :placeholder="engine==='model'?'用一句话描述你想找的数据、分组或统计结果…':'输入条件，例如：score 大于 0.9，按 score 降序 前 20 行'" :disabled="!supported||loading" @keydown.ctrl.enter.prevent="run" @keydown.meta.enter.prevent="run"/></div>
          <div class="query-examples"><span>试一试</span><button v-for="item in suggestions" :key="item" type="button" :disabled="loading" @click="example(item)">{{item}}<ArrowRight :size="12"/></button></div>
          <div v-if="engine==='model'" class="model-consent"><label><input v-model="allowExternalSchema" type="checkbox" :disabled="!sourceCommit||loading"/><span>允许向 OpenAI 发送字段名、类型和查询问题。<small>数据记录留在本机，结果由本地执行生成。</small></span></label><button type="button" :disabled="!columns.length" @click="showFields=!showFields">{{showFields?'收起字段':'查看字段'}}<ChevronDown :size="13"/></button><div v-if="showFields" class="consent-fields"><code v-for="column in columns" :key="column.name">{{column.name}}<small>{{column.dtype}}</small></code></div></div>
          <p v-else class="rule-mode-note"><Code2 :size="14"/>支持比较、包含、AND、按列排序、前 N 行和统计总数。无需发送到模型。</p>
          <footer class="query-submit-bar"><span><GitCommitHorizontal :size="14"/><code>{{branch}}</code><span v-if="sourceCommit">· {{sourceCommit.slice(0,10)}}</span></span><button v-if="!authenticated" type="button" class="btn btn-primary" @click="openIdentity">登录后执行查询</button><button v-else class="btn btn-primary" :disabled="!canRun"><LoaderCircle v-if="loading" class="spin" :size="16"/><Play v-else :size="15"/>{{loading?'正在执行…':'运行查询'}}<kbd v-if="!loading">⌘ / Ctrl ↵</kbd></button></footer></form>
        </section>
        <p v-if="!supported" class="notice">当前服务尚未启用查询能力，请检查服务连接。</p>
        <div v-if="error" class="error-state" role="alert"><span>{{error}}</span><button class="btn" :disabled="!canRun" @click="run">重试查询</button></div>
        <section v-if="result" class="query-results panel" aria-label="查询结果"><header class="result-heading"><div class="result-tabs"><button :class="{active:resultView==='rows'}" @click="resultView='rows'"><Table2 :size="15"/>结果<span>{{result.rows.length.toLocaleString()}}</span></button><button v-if="result.plan" :class="{active:resultView==='plan'}" @click="resultView='plan'"><Braces :size="15"/>只读执行计划</button></div><span class="result-engine"><Check :size="13"/>{{result.engine==='codex-plan'?'模型计划':result.engine==='local-rules'?'本地规则':result.engine}}</span></header>
          <div class="result-summary"><strong>已展示 {{result.rows.length.toLocaleString()}} / {{result.totalRows.toLocaleString()}} 条匹配结果</strong><span v-if="result.scannedRows!==undefined">扫描 {{result.scannedRows.toLocaleString()}}<template v-if="result.sourceRows!==undefined"> / {{result.sourceRows.toLocaleString()}}</template> 行</span></div>
          <p v-if="returnedRange.partial" class="query-range"><template v-if="result.rows.length">本次返回第 {{returnedRange.start.toLocaleString()}}–{{returnedRange.end.toLocaleString()}} 条结果。</template><template v-else>偏移 {{returnedRange.offset.toLocaleString()}} 后没有返回记录。</template><span v-if="returnedRange.limit"> 计划最多返回 {{returnedRange.limit.toLocaleString()}} 条。</span>可调整问题中的条数范围后重新查询。</p>
          <div v-if="resultView==='rows'" class="query-table-scroll"><table class="data-table query-table"><thead><tr><th class="result-row-number">#</th><th v-for="column in result.columns" :key="column.name">{{column.name}}<small>{{column.dtype}}</small></th></tr></thead><tbody><tr v-for="(row,index) in result.rows" :key="index"><td class="result-row-number">{{returnedRange.offset+index+1}}</td><td v-for="column in result.columns" :key="column.name"><details v-if="row[column.name]!==null&&typeof row[column.name]==='object'"><summary>查看 JSON</summary><pre>{{JSON.stringify(row[column.name],null,2)}}</pre></details><span v-else :title="cell(row[column.name])" :class="{'cell-null':row[column.name]===null}">{{cell(row[column.name])}}</span></td></tr></tbody></table><div v-if="!result.rows.length" class="empty"><Search :size="27"/><h3>{{result.totalRows?'当前范围没有记录':'没有匹配结果'}}</h3><p>调整查询条件或返回范围后重试。</p></div></div>
          <pre v-else class="query-plan">{{JSON.stringify(result.plan,null,2)}}</pre>
          <details class="query-explanation"><summary>查看查询说明</summary><p>{{result.explanation}}</p><p v-if="context"><code>{{context.ref}}</code><span>{{context.path}}</span></p></details>
        </section>
        <div v-else class="query-ready-state"><LoaderCircle v-if="loading||sourceLoading" class="spin" :size="24"/><Database v-else :size="29" :stroke-width="1.4"/><h3>{{loading?'正在查询数据':sourceLoading?'正在加载数据结构':sourceCommit?'数据已就绪，开始查询':'选择一个数据集开始'}}</h3><p>{{sourceCommit?'查询不会修改原始数据。结果、计数和执行说明会显示在这里。':'支持 JSONL、CSV、TSV、Parquet 和 Arrow 表格。'}}</p></div>
      </div>
      <aside class="query-schema panel"><header><div><Database :size="15"/><strong>数据结构</strong></div><span>{{columns.length}} 个字段</span></header><div v-if="sourceCommit" class="schema-source"><strong>{{fileName}}</strong><span>{{sourceRows?.toLocaleString()}} 行 · {{branch}}</span></div><div v-if="sourceLoading" class="schema-loading"><LoaderCircle class="spin" :size="17"/>读取字段中…</div><div v-else-if="!columns.length" class="schema-empty"><FileText :size="24"/><p>选择数据文件后查看字段名与类型。</p></div><div v-else class="schema-fields"><button v-for="column in columns" :key="column.name" :title="`将字段 ${column.name} 加入查询`" @click="insertField(column.name)"><span>{{column.name}}</span><code>{{column.dtype}}</code></button></div><footer v-if="columns.length">点击字段名加入查询。<br/>当前结果固定到加载时的数据版本。</footer></aside>
    </div>
  </section>
</template>

<style scoped>
